/// <summary>
/// Sales order cancelled business event.
/// </summary>
[BusinessEvents(classStr(METSalesOrderCancelledBusinessEventContract), '@MET:SOCancellationBusinessEvent', '@MET:SOCancellationBusinessEventDesc', ModuleAxapta::SalesOrder)]
public final class METSalesOrderCancelledBusinessEvent extends BusinessEventsBase
{
    private SalesTable salesTable;

}

Method.Source:
    /// <summary>
    /// gets/sets the salesTable buffer
    /// </summary>
    /// <param name = "_salesTable">salesTable buffer</param>
    /// <returns>salesTable buffer</returns>
    private SalesTable parmSalesTable(SalesTable _salesTable = salesTable)
    {
        salesTable = _salesTable;

        return salesTable;
    }

    /// <summary>
    /// Create a new instance of <c>METSalesOrderCancelledBusinessEvent</c>
    /// </summary>
    /// <param name = "_salesTable">salesTable buffer</param>
    /// <returns>returns instance of <c>METSalesOrderCancelledBusinessEvent</c></returns>
    public static METSalesOrderCancelledBusinessEvent newFromSalesCancellation(SalesTable _salesTable)
    {
        METSalesOrderCancelledBusinessEvent event = new METSalesOrderCancelledBusinessEvent();

        event.salesTable = _salesTable;

        return event;
    }

/// <summary>
/// Constructs a new METSalesOrderCancelledBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSalesOrderCancelledBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return METSalesOrderCancelledBusinessEventContract::newFromSalesCancellation(salesTable);
}
